import type { Node } from './../../../ricos-schema/next-schema/index.js';
import { getNodeAnimation } from './../../../_shared/node-animation/get-node-animation.js';

/** Early-exit recursive scan: does any node in the tree carry an animation? */
export const hasAnimatedNodes = (nodes: Node[]): boolean =>
  nodes.some(node => Boolean(getNodeAnimation(node)) || hasAnimatedNodes(node.nodes ?? []));
