import type { RichContent } from './../../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { RicosDocument, RicosDocumentNode } from './../../../ricos-schema/next-schema/index.js';
import { Node_Type } from './../../../ricos-schema/next-schema/index.js';

/**
 * Fullscreen expand traversal uses the next-schema document model.
 * Viewer content is typed as legacy `RichContent`; in the current schema
 * generation those shapes are structurally the same document graph.
 */
export const toFullscreenDocument = (content: RichContent): RicosDocument =>
  content as unknown as RicosDocument;

export const isFullscreenExpandableNode = (
  node: RicosDocumentNode
): node is Extract<RicosDocumentNode, { type: 'IMAGE' | 'GALLERY' }> =>
  node.type === Node_Type.IMAGE || node.type === Node_Type.GALLERY;
