import React, { useEffect, useMemo } from 'react';

import type { RichContent } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { Node as RicosDocumentNode } from './../../ricos-schema/next-schema/index.js';

import { hasAnimatedNodes } from './utils/has-animated-nodes.js';
import { hasPointerAnimatedNodes } from './utils/has-pointer-animated-nodes.js';

/** Marks the element that bounds one viewer instance's reveal contract. */
export const ANIMATION_SCOPE_ATTR = 'data-ricos-animation-scope';

/**
 * Matches animated nodes belonging to one viewer instance only.
 *
 * The scope exists because the rules below live in a document-level stylesheet while
 * the runtime only ever queries inside its own `contentRef`: an unscoped rule lets one
 * viewer hide another viewer's nodes with nothing able to reveal them. Scoping to the
 * runtime's own root makes "what the CSS can reach" and "what the runtime can reach"
 * the same set.
 *
 * The value is matched unquoted, so `scopeId` must be a bare CSS identifier — see the
 * escaping note on the builders below.
 */
export const animationScopeSelector = (scopeId: string) =>
  `[${ANIMATION_SCOPE_ATTR}=${scopeId}] [data-ricos-animation]`;

/**
 * The hide rules key off `data-ricos-entrance`, not `data-ricos-animation`: only nodes
 * with an entrance effect are hidden until played. A loop-only node animates in place
 * and must stay visible from first paint — nothing would ever reveal it otherwise.
 */
const entranceScopeSelector = (scopeId: string) =>
  `[${ANIMATION_SCOPE_ATTR}=${scopeId}] [data-ricos-entrance]`;

// Reveal contract (owned by ricos, see adr/003): entrance-marked nodes are
// hidden from first paint (SSR-safe — this <style> is part of the server-rendered
// HTML) until the lazy runtime marks them entered. Media-gated so reduced-motion
// users always see content, <noscript> unhides for no-JS visitors.
//
// The scope root also clips overflow: animation transforms (Rubber scales past 1,
// Poke/Cross translate, Skew/Track push hundreds of px) paint outside the content
// column, and with `overflow: visible` all the way up the chain that overhang joins
// the page's scrollable overflow — a horizontal scrollbar flashing on every loop
// cycle, and (for mouse effects, whose inline transform persists wherever the pointer
// rests) a vertical scrollbar growing past the document end whenever the LAST node is
// displaced downward. Clipping sits on the scope root, not the animated node: overflow
// clips an element's content, never its own transformed box, and the LIST_ITEM target
// has no wrapper at all. `clip` and not `hidden` — hidden would make the viewer a
// scroll container and coerce the sibling axis to auto, while clip is paint-only. The
// clip must also be HARD: scrollable overflow excludes only content that is actually
// clipped away, so an `overflow-clip-margin` re-admits exactly the scroll growth it
// lets paint (verified in Chromium — clip with a margin scrolls identically to
// visible). Paint-without-scroll does not exist for transformed boxes, which forces
// the axis split below.
//
// x is clipped for every animated doc; y only when the doc has mouse effects. Vertical
// travel from entrance/loop effects (Bounce, from-BOTTOM entrances) overhangs only
// transiently, so those docs keep their unclipped vertical look — but a mouse effect
// holds its displacement for as long as the pointer sits there, pumping the host
// page's scrollbar with every move, so pointer docs take the both-axis clip and the
// effect cuts at the viewer's box edge instead (exactly how x already behaves for
// everything). Under the same media gate as the hide rule: with reduced motion the
// runtime never plays, nothing overflows, and those users keep exactly today's layout
// behavior.
//
// These strings must not contain " ' < > or &. They are rendered as a <style> text
// child (daf81fa3b3 deliberately moved off React's raw-HTML escape hatch); the server
// renderer escapes text children, and <style> is an HTML raw-text element where
// character references are NOT decoded — so an escaped character would work on the
// client and silently break in SSR HTML. That is why the attribute value is unquoted.
const animationCss = (scopeId: string, hasPointerNodes: boolean) =>
  `@media (prefers-reduced-motion: no-preference){` +
  `[${ANIMATION_SCOPE_ATTR}=${scopeId}]{${hasPointerNodes ? 'overflow:clip' : 'overflow-x:clip'}}` +
  `${entranceScopeSelector(scopeId)}:not([data-ricos-entered]){visibility:hidden}}`;
const noscriptCss = (scopeId: string) =>
  `${entranceScopeSelector(scopeId)}{visibility:visible !important}`;

// <noscript> only covers the no-JS case. If the runtime chunk fails to load (CSP,
// ad-blocker, flaky CDN, sandboxed iframe embeds) or throws during init, this reveals
// content that would otherwise stay hidden by HIDE_CSS forever — fail open, never hide
// real content because a script didn't run.
const revealAll = (root: HTMLElement) =>
  root
    .querySelectorAll<HTMLElement>('[data-ricos-animation]')
    .forEach(el => el.setAttribute('data-ricos-entered', ''));

type Props = {
  /**
   * Declared as the proto `RichContent` because that's what `ContentViewerProps.content`
   * is typed as, even though the next viewer receives `RicosDocument`-shaped content at
   * runtime. Taking the declared type and narrowing below keeps that discrepancy inside
   * this module instead of putting a double cast at the ContentViewer boundary.
   */
  content?: RichContent;
  contentRef: React.RefObject<HTMLDivElement | null>;
  /** Gated on `pluginAnimationViewer` presence (strict opt-in) — see content-viewer.tsx. */
  enabled: boolean;
  /**
   * Identifies this viewer instance. ContentViewer puts the same value in
   * `ANIMATION_SCOPE_ATTR` on the `contentRef` element, which is what bounds the rules
   * below. Owned there rather than here because the attribute has to be in the
   * server-rendered HTML — written from an effect it would land after first paint,
   * leaving the SSR `<style>` matching nothing and flashing the content it exists to hide.
   */
  scopeId: string;
};

/**
 * Core viewer entrance-animation mount: rendered by ContentViewer whenever
 * `pluginAnimationViewer` is registered, but costs nothing unless the document
 * actually contains animations — the motion runtime loads via dynamic import()
 * only then (zero bundle cost otherwise).
 */
export const NodeAnimations: React.FC<Props> = ({ content, contentRef, enabled, scopeId }) => {
  // the single narrowing of the proto/next content discrepancy described on Props;
  // memoized so the identity stays stable per content and the effect below doesn't re-init
  const nodes = useMemo(() => (content?.nodes ?? []) as unknown as RicosDocumentNode[], [content]);
  const hasAnimations = useMemo(() => enabled && hasAnimatedNodes(nodes), [enabled, nodes]);
  const hasPointerNodes = useMemo(
    () => hasAnimations && hasPointerAnimatedNodes(nodes),
    [hasAnimations, nodes]
  );

  useEffect(() => {
    if (!hasAnimations || !contentRef.current) {
      return;
    }
    let cancelled = false;
    let dispose: (() => void) | undefined;
    import('./node-animations-runtime.js')
      .then(runtime => {
        if (cancelled || !contentRef.current) {
          return;
        }
        try {
          dispose = runtime.initNodeAnimations(contentRef.current, nodes);
        } catch {
          revealAll(contentRef.current);
        }
      })
      .catch(() => {
        if (!cancelled && contentRef.current) {
          revealAll(contentRef.current);
        }
      });
    return () => {
      cancelled = true;
      dispose?.();
    };
  }, [nodes, hasAnimations, contentRef]);

  if (!hasAnimations) {
    return null;
  }

  return (
    <>
      <style>{animationCss(scopeId, hasPointerNodes)}</style>
      {/* No-JS reveal. The server renderer emits the nested <style> verbatim
          (verified on react-dom 18.3 and 19.2), while the client renderer silently
          drops <noscript> children (<noscript> forces shouldSetTextContent) —
          harmless, since with JS enabled <noscript> is inert and the reveal is
          unnecessary. Known risk: that client-side drop is undocumented — if a
          future React starts rendering the child, a live <style> inside <noscript>
          DOES apply (noscript inertness is parse-time only) and would force-reveal
          every animated node. A plain string child is not an option: the server
          renderer HTML-escapes it, so no-JS visitors would see the raw CSS as page
          text and never get the reveal. A CSS-only `@media (scripting: enabled)`
          alternative was also rejected: it doesn't detect script-blocking browser
          extensions (NoScript/uBlock-style), which would leave content hidden
          forever for those visitors — a regression <noscript> doesn't have. */}
      <noscript>
        <style>{noscriptCss(scopeId)}</style>
      </noscript>
    </>
  );
};
