import React from 'react';

import type { Node_Type, RicosDocumentNode } from './../../../../ricos-schema/next-schema/index.js';
import type { NodeViewDecorator } from './../../../../ricos-types/index.js';
import { getNodeAnimation } from './../../../../_shared/node-animation/get-node-animation.js';
import { hasEntranceAnimation } from './../../../../_shared/node-animation/has-entrance-animation.js';

/**
 * Node types whose viewer renderer spreads getAnimationDomAttrs onto its own
 * DOM element instead of relying on this wrapper — a div between `<ul>` and
 * `<li>` is invalid HTML.
 */
const SELF_ANIMATED_TYPES: ReadonlySet<string> = new Set<Node_Type>(['LIST_ITEM']);

/**
 * Wraps every animated node (any depth) in a block-level div carrying the
 * reveal contract: `data-ricos-animation` marks the animation target (value =
 * node id, resolved to a Animation by the lazy runtime), and the runtime
 * sets `data-ricos-entered` when the node's animation is first triggered.
 * `data-ricos-entrance` additionally marks the nodes with an entrance effect —
 * only those are kept invisible by the SSR hide CSS in <NodeAnimations> until
 * entered; loop-only nodes animate in place and must stay visible from first
 * paint. A plain div (not display:contents) — WAAPI transforms need a box.
 */
export const AnimationDecorator: NodeViewDecorator<JSX.Element> = {
  rule: node =>
    Boolean(getNodeAnimation(node as unknown as RicosDocumentNode)) &&
    !SELF_ANIMATED_TYPES.has(node.type),
  decorate: ({ node, element }) => (
    <div
      data-ricos-animation={node.id}
      {...(hasEntranceAnimation(getNodeAnimation(node as unknown as RicosDocumentNode))
        ? { 'data-ricos-entrance': '' }
        : {})}
    >
      {element}
    </div>
  ),
};
