import classnames from 'classnames';
import type { FC } from 'react';
import React, { useContext } from 'react';

import {
  RicosAlignmentContext,
  RicosNodeContextProvider,
  VisibleIndentationContext,
  VisibleIndentationContextProvider,
} from './../../../../../ricos-context/index.js';
import { TextStyle_TextAlignment } from './../../../../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { CheckboxListNode } from './../../../../../ricos-schema/next-schema/index.js';
import type { NodeViewRenderer, NodeViewRendererProps } from './../../../../../ricos-types/index.js';
import { CHECKBOX_LIST_STYLE_ATTRIBUTE_VALUE } from './../../../../../_shared/list-checkbox/checkbox-list-style.js';

import alignmentStyle from '../../../../statics/alignment-scss.js';
import styles from './lists-scss.js';

const CheckboxList: FC<NodeViewRendererProps> = ({ node, nodeIndex, RicosNodesRenderer }) => {
  const checkboxListNode = node as CheckboxListNode;
  const { textAlignment } = useContext(RicosAlignmentContext);
  const { visibleIndentation } = useContext(VisibleIndentationContext);

  const currIndentation = visibleIndentation?.indentation || 0;
  const currOffset = checkboxListNode.checkboxListData?.offset || 0;

  const indentation =
    (visibleIndentation && visibleIndentation?.nodeId !== node.id ? 1 : 0) +
    currIndentation +
    currOffset;

  const checkboxListClassName = classnames(
    styles.bulletedlist,
    styles.checkboxList,
    alignmentStyle[textAlignment || TextStyle_TextAlignment.AUTO]
  );

  return (
    <ul className={checkboxListClassName} data-list-style={CHECKBOX_LIST_STYLE_ATTRIBUTE_VALUE}>
      <VisibleIndentationContextProvider visibleIndentation={{ indentation, nodeId: node.id }}>
        <RicosNodeContextProvider parentNode={node} parentIndex={nodeIndex}>
          <RicosNodesRenderer nodes={node.nodes ?? []} />
        </RicosNodeContextProvider>
      </VisibleIndentationContextProvider>
    </ul>
  );
};

const CheckboxListRenderer: NodeViewRenderer = ({ node, ...props }) => {
  return <CheckboxList key={node.id} node={node} {...props} />;
};

export default CheckboxListRenderer;
