import { pipe } from 'fp-ts-esm/function';

import { GALLERY_TYPE, IMAGE_TYPE } from './../ricos-content/index.js';
import type { DebugMode, PluginMapping, PluginTypeMapper } from './../ricos-types/index.js';
import { deepMerge } from './../_shared/deep-merge.js';
import {
  convertRelObjectToString,
  convertRelStringToObject,
} from './../wix-rich-content-common/lib/link-converters.js';

import { applyBIGenerics } from './biUtils/index.js';
import { isViewerPlugin } from './is-viewer-plugin.js';
import { pluginsStrategy } from './plugins-strategy.js';
import type { ContentViewerProps, RicosViewerProps } from './types.js';

const combineMappers = (mappers: PluginTypeMapper[], ...args: $TSFixMe[]): PluginMapping => {
  if (!mappers || mappers.some(resolver => typeof resolver !== 'function')) {
    console.warn(`${mappers} is expected to be a function array`); // oxlint-disable-line no-console
    return {};
  }
  return mappers.reduce<PluginMapping>((map, mapper) => Object.assign(map, mapper(...args)), {});
};

export function mergeViewerProps({
  pluginConfig,
  helpers,
  isMobile,
  addAnchors,
  onError,
  mediaSettings = {},
  linkSettings = {},
  generalLinkSettings,
  textAlignment,
  experiments,
  iframeSandboxDomain,
  theme,
  plugins = [],
  content,
  viewerProps,
  onNodeClick,
  debugMode,
  jsdomMode,
  baseUrl,
}: RicosViewerProps & {
  viewerProps: Partial<ContentViewerProps>;
  debugMode?: DebugMode[];
  pluginConfig?: Record<string, any>;
  helpers?: Record<string, any>;
}) {
  const rcvPluginProps = pluginsStrategy({
    plugins: plugins?.filter(isViewerPlugin),
    viewerProps,
  });

  const { pauseMedia, disableRightClick, userDomainMedia } = mediaSettings;
  const { customAnchorScroll } = linkSettings;
  let { anchorTarget = '_blank', relValue, rel } = linkSettings;

  if (relValue) {
    // oxlint-disable-next-line no-console
    console.warn(
      // oxlint-disable-next-line max-len
      `relValue is deprecated, Please use rel prop instead.`
    );
    rel = convertRelStringToObject(relValue) || rel;
  }
  const { target, ...relAttributes } = generalLinkSettings?.initialLinkOptions || {};
  anchorTarget = target || anchorTarget;
  rel = { ...rel, ...relAttributes };
  relValue = convertRelObjectToString(rel);
  const disableDownload = mediaSettings?.disableDownload || disableRightClick;
  // any of ricos props that should be merged into child
  const ricosPropsToMerge: Partial<ContentViewerProps> = {
    addAnchors,
    isMobile,
    config: {
      uiSettings: { disableDownload },
    },
    content,
    onError,
    helpers: {},
    disabled: pauseMedia,
    anchorTarget,
    relValue,
    customAnchorScroll,
    textAlignment,
    experiments,
    iframeSandboxDomain,
    theme,
    onNodeClick,
    jsdomMode,
    baseUrl,
    userDomainMedia,
  };

  const mergedRCProps = pipe(
    deepMerge(
      { locale: 'en', config: {} },
      rcvPluginProps,
      { config: pluginConfig, helpers: helpers },
      ricosPropsToMerge,
      viewerProps
    ),
    applyBIGenerics(() => content?.metadata?.id)
  ) as ContentViewerProps & { typeMappers: PluginTypeMapper[] | PluginMapping };

  return {
    ...mergedRCProps,
    debugMode,
    plugins,
    typeMappers: combineMappers((mergedRCProps.typeMappers || []) as PluginTypeMapper[]),
  };
}

export function hasFullscreen(config: $TSFixMe) {
  const { [IMAGE_TYPE]: imageConfig, [GALLERY_TYPE]: galleryConfig } = config || {};
  const needsFullscreenProvider = !imageConfig?.onExpand || !galleryConfig?.onExpand;
  const isExpandDisabled =
    (!imageConfig || imageConfig.disableExpand) && (!galleryConfig || galleryConfig?.disableExpand);

  return !isExpandDisabled && needsFullscreenProvider;
}
