import type { FC, ReactElement } from 'react';
import React from 'react';

type AnchorableProps = {
  nodeId: string;
  children: ReactElement;
};

export const Anchorable: FC<AnchorableProps> = ({ nodeId, children }) => {
  // tabIndex={-1} keeps the target out of the normal Tab order while allowing
  // programmatic focus, so anchor/deep-link navigation can move keyboard focus
  // to the section (WCAG 2.4.3 Focus Order). Rides the same cloneElement that
  // injects the id, so it lands on the same focusable DOM node.
  return React.cloneElement(React.Children.only(children), {
    id: `viewer-${nodeId}`,
    tabIndex: -1,
  });
};
