import type { ReactElement } from 'react';
import React, { Fragment, Suspense } from 'react';

import { extract } from './../../../ricos-content/RicosContentAPI/extract-next.js';
import type { RichContent } from './../../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { RicosDocument, RicosDocumentNode } from './../../../ricos-schema/next-schema/index.js';
import { Node_Type } from './../../../ricos-schema/next-schema/index.js';
import type {
  AvailableExperiments,
  FullscreenProps,
  Helpers,
  LegacyViewerPluginConfig,
  TFunction,
  UserDomainMediaConfig,
} from './../../../ricos-types/index.js';
import { getCroppedImage } from './../../../_shared/media/get-cropped-image.js';
import type { NormalizedGalleryItem } from './../../../plugin-gallery/media/normalize-gallery-items.js';
import { normalizeGalleryItems } from './../../../plugin-gallery/media/normalize-gallery-items.js';

import { isFullscreenExpandableNode, toFullscreenDocument } from './to-fullscreen-document.js';

interface Props {
  children: (args: { config: LegacyViewerPluginConfig; onHover: () => void }) => ReactElement;
  config: LegacyViewerPluginConfig;
  helpers?: Helpers;
  content?: RichContent;
  isMobile: boolean;
  fullscreenProps?: FullscreenProps;

  experiments?: AvailableExperiments;
  jsdomMode?: boolean;
  t: TFunction;
  userDomainMedia?: UserDomainMediaConfig;
}

type ExpandModeData = {
  items: NormalizedGalleryItem[];
  itemRanges: Record<string, { startIndex: number; itemCount: number }>;
};

const loadFullscreenModal = () =>
  import(/* webpackChunkName: "ricos_FullscreenModalViewer"  */ './fullscreen-modal.js');

const FullscreenModal = React.lazy(loadFullscreenModal);

export const FullscreenProvider: React.FC<Props> = props => {
  const { children, isMobile, fullscreenProps, content } = props;
  const lastInteractionRef = React.useRef<HTMLElement>();
  const [state, setState] = React.useState<
    | {
        type: 'open';
        activeIndex: number;
        restoreFocusTo?: HTMLElement;
      }
    | { type: 'closed' }
  >({ type: 'closed' });

  React.useEffect(() => {
    // The inline renderer may move focus before invoking onExpand, so remember the exact trigger.
    const recordInteraction = (event: Event) => {
      const target = event.target;
      if (!(target instanceof HTMLElement)) {
        return;
      }
      lastInteractionRef.current = target.closest<HTMLElement>('button, a, [tabindex]') || target;
    };
    document.addEventListener('pointerdown', recordInteraction, true);
    document.addEventListener('keydown', recordInteraction, true);
    return () => {
      document.removeEventListener('pointerdown', recordInteraction, true);
      document.removeEventListener('keydown', recordInteraction, true);
    };
  }, []);

  const expandModeData: ExpandModeData = React.useMemo(() => {
    if (content) {
      return getExpandModeData(toFullscreenDocument(content));
    }
    return { items: [], itemRanges: {} };
  }, [content]);

  const addExpand = (config: LegacyViewerPluginConfig) => {
    const onExpand = (nodeId: string, innerIndex = 0) => {
      const activeIndex = getExpandIndex(expandModeData, nodeId, innerIndex);
      if (activeIndex === undefined) {
        return;
      }
      const activeElement = document.activeElement;
      const lastInteraction = lastInteractionRef.current;
      setState({
        type: 'open',
        activeIndex,
        restoreFocusTo:
          lastInteraction?.isConnected && lastInteraction !== document.body
            ? lastInteraction
            : activeElement instanceof HTMLElement
              ? activeElement
              : undefined,
      });
    };
    const newConfig = { ...config };
    const imageConfig = config['wix-draft-plugin-image'];
    const galleryConfig = config['wix-draft-plugin-gallery'];
    if (imageConfig && !imageConfig.onExpand) {
      newConfig['wix-draft-plugin-image'] = { ...imageConfig, onExpand };
    }
    if (galleryConfig && !galleryConfig.onExpand) {
      newConfig['wix-draft-plugin-gallery'] = { ...galleryConfig, onExpand };
    }
    return newConfig;
  };

  return (
    <Fragment>
      {children({ config: addExpand(props.config), onHover: () => loadFullscreenModal() })}
      {state.type === 'open' && (
        <Suspense fallback={<div />}>
          <FullscreenModal
            items={expandModeData.items}
            onClose={() => setState({ type: 'closed' })}
            index={state.activeIndex}
            restoreFocusTo={state.restoreFocusTo}
            isMobile={isMobile}
            {...fullscreenProps}
            jsdomMode={props.jsdomMode}
            t={props.t}
            userDomainMedia={props.userDomainMedia}
          />
        </Suspense>
      )}
    </Fragment>
  );
};

export const getExpandModeData = (content: RicosDocument): ExpandModeData => {
  const items: NormalizedGalleryItem[] = [];
  const itemRanges: ExpandModeData['itemRanges'] = {};

  extract(content.nodes)
    .get()
    .forEach((node, nodeIndex) => {
      if (!isFullscreenExpandableNode(node)) {
        return;
      }
      const nodeKey = node.id || `fullscreen-node:${nodeIndex}`;
      const nodeItems = normalizeNodeItems(node, nodeKey);
      if (node.id) {
        itemRanges[node.id] = { startIndex: items.length, itemCount: nodeItems.length };
      }
      items.push(...nodeItems);
    });

  return { items, itemRanges };
};

export const getExpandIndex = (
  data: ExpandModeData,
  nodeId: string,
  innerIndex = 0
): number | undefined => {
  const range = data.itemRanges[nodeId];
  if (!range || range.itemCount === 0) {
    return undefined;
  }
  const requestedIndex = Number.isFinite(innerIndex) ? Math.trunc(innerIndex) : 0;
  return range.startIndex + Math.min(Math.max(requestedIndex, 0), range.itemCount - 1);
};

const normalizeNodeItems = (
  node: Extract<RicosDocumentNode, { type: 'IMAGE' | 'GALLERY' }>,
  nodeKey: string
): NormalizedGalleryItem[] => {
  switch (node.type) {
    case Node_Type.IMAGE: {
      if (!node.imageData.image?.src || node.imageData.disableExpand) {
        return [];
      }
      return normalizeGalleryItems({
        items: [
          {
            image: { media: getFullscreenImageMedia(node) },
            altText: node.imageData.altText,
          },
        ],
        nodeId: nodeKey,
        disableDownload: node.imageData.disableDownload,
      });
    }
    case Node_Type.GALLERY: {
      if (node.galleryData.disableExpand) {
        return [];
      }
      return normalizeGalleryItems({
        items: node.galleryData.items,
        nodeId: nodeKey,
        disableDownload: node.galleryData.disableDownload,
      });
    }
  }
};

const getFullscreenImageMedia = (node: Extract<RicosDocumentNode, { type: 'IMAGE' }>) => {
  const media = node.imageData.image;
  const croppedImage = getCroppedImage({
    mediaId: media?.src?.id,
    sourceWidth: media?.width,
    sourceHeight: media?.height,
    crop: node.imageData.crop,
  });

  return croppedImage
    ? {
        ...media,
        src: { url: croppedImage.url },
        width: croppedImage.width,
        height: croppedImage.height,
      }
    : { ...media };
};
