import classnames from 'classnames';
import type { FC } from 'react';
import React, { useContext } from 'react';

import { ANIMATION_TYPE } from './../../../../../ricos-content/index.js';
import {
  RicosAlignmentContext,
  RicosDirectionHandledContextProvider,
  RicosNodeContext,
  RicosNodeContextProvider,
  RicosViewerContext,
  VisibleIndentationContext,
} from './../../../../../ricos-context/index.js';
import type { Node } from './../../../../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import { TextStyle_TextAlignment } from './../../../../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { ListItemNode } from './../../../../../ricos-schema/next-schema/index.js';
import {
  Decoration_Type,
  type NodeViewRenderer,
  type NodeViewRendererProps,
  Node_Type,
} from './../../../../../ricos-types/index.js';
import { hasPlugin } from './../../../../../_shared/has-plugin.js';
import { CHECKBOX_LIST_STYLE_ATTRIBUTE_VALUE } from './../../../../../_shared/list-checkbox/checkbox-list-style.js';
import { getBlockDefaultFontSize } from './../../../../../_shared/list-checkbox/get-block-default-font-size.js';
import { getAnimationDomAttrs } from './../../../../../_shared/node-animation/get-animation-dom-attrs.js';
import { getListSymbol, normalizeOffset } from './../../../../../wix-rich-content-common/index.js';

import { getPaywallSeoClass, isPaywallSeo } from '../../utils/paywall-seo.js';
import { levelToClassName } from '../heading/heading.js';
import { getStartMargin } from './get-start-margin.js';
import styles from './lists-scss.js';

const ListItem: FC<NodeViewRendererProps> = ({ node, nodeIndex, RicosNodesRenderer }) => {
  const listItemNode = node as ListItemNode;
  const { seoMode, plugins } = useContext(RicosViewerContext);
  const { parentIndex } = useContext(RicosNodeContext);
  const { visibleIndentation } = useContext(VisibleIndentationContext);

  const firstChild = node.nodes[0];
  const dataProperty = `${firstChild?.type?.toLowerCase()}Data`;
  const { textAlignment } = (firstChild?.[dataProperty as keyof Node] as $TSFixMe)?.textStyle || {};
  const { textAlignment: parentAlignment } = useContext(RicosAlignmentContext);
  const finalAlignment =
    textAlignment && textAlignment !== TextStyle_TextAlignment.AUTO
      ? textAlignment
      : parentAlignment;
  const listStylePosition = textAlignment && textAlignment === TextStyle_TextAlignment.CENTER;
  const { parentNode } = useContext(RicosNodeContext);

  const indentation =
    visibleIndentation && visibleIndentation?.nodeId === parentNode?.id
      ? normalizeOffset(visibleIndentation?.indentation)
      : 0;

  const marginInlineStart = getStartMargin(parentNode, visibleIndentation?.indentation || 0);
  const isCheckboxList = parentNode?.type === Node_Type.CHECKBOX_LIST;
  const marker = isCheckboxList
    ? 'none'
    : parentNode
      ? getListSymbol(indentation, parentNode.type)
      : '';

  const isParentOfHeading = firstChild?.type === Node_Type.HEADING;
  const headingLevel = isParentOfHeading && firstChild.headingData?.level;

  const listItemClassName = classnames(
    styles.listItem,
    isPaywallSeo(seoMode) && getPaywallSeoClass(seoMode?.paywall || {}, nodeIndex + parentIndex)
  );

  const childFontSize = firstChild?.nodes?.[0]?.textData?.decorations?.find(
    decoration => decoration.type === Decoration_Type.FONT_SIZE
  )?.fontSizeData?.value;

  // When the chosen font is smaller than the block's own default, shrink the
  // child paragraph/heading to match so its line box (and the marker) don't stay
  // oversized — see `data-child-font-fit` in `list-checkbox.scss`.
  const shouldFitChildFont =
    !!childFontSize && childFontSize < getBlockDefaultFontSize(headingLevel || undefined);

  // Same gate as AnimationDecorator (rericos/decorators/index.ts): without
  // pluginAnimationViewer no runtime reveals these nodes, so the attribute is dead markup.
  // The hide CSS is scoped to its own viewer instance (node-animations.tsx), so this keeps
  // the DOM honest rather than being the only thing preventing a permanent hide.
  const animationDomAttrs = hasPlugin(ANIMATION_TYPE, plugins) ? getAnimationDomAttrs(node) : {};

  return (
    <li
      dir="auto"
      aria-level={indentation + 1}
      className={listItemClassName}
      style={
        {
          textAlign: finalAlignment,
          fontSize: childFontSize,
          marginInlineStart,
          listStyleType: marker,
        } as React.CSSProperties
      }
      {...(shouldFitChildFont ? { 'data-child-font-fit': 'true' } : {})}
      {...(headingLevel
        ? {
            'data-heading-level': levelToClassName[headingLevel as keyof typeof levelToClassName],
          }
        : {})}
      {...(listStylePosition ? { 'data-list-style-position': 'inside' } : {})}
      {...(isCheckboxList
        ? {
            'data-list-style': CHECKBOX_LIST_STYLE_ATTRIBUTE_VALUE,
            role: 'checkbox',
            'aria-checked': listItemNode.listItemData?.checked ? 'true' : 'false',
          }
        : {})}
      {...animationDomAttrs}
    >
      {isCheckboxList && (
        // Viewer marker is presentational only; the actual checkbox control exists only in editing.
        <span
          aria-hidden
          className={styles.checkboxInput}
          aria-checked={listItemNode.listItemData?.checked ? 'true' : 'false'}
        />
      )}
      <RicosDirectionHandledContextProvider directionHandled>
        <RicosNodeContextProvider parentNode={node} parentIndex={nodeIndex}>
          <RicosNodesRenderer nodes={node.nodes ?? []} shouldParagraphApplyTextStyle />
        </RicosNodeContextProvider>
      </RicosDirectionHandledContextProvider>
    </li>
  );
};

const ListItemRenderer: NodeViewRenderer = ({ node, ...props }) => {
  return <ListItem key={node.id} node={node} {...props} />;
};

export default ListItemRenderer;
