/* oxlint-disable jsx-a11y/no-static-element-interactions */
/* oxlint-disable jsx-a11y/mouse-events-have-key-events */
/* oxlint-disable jsx-a11y/aria-props */
/* oxlint-disable jsx-a11y/no-noninteractive-element-interactions */
import classNames from 'classnames';
import React, { useCallback, useLayoutEffect, useRef, useState } from 'react';

import { ANIMATION_TYPE, SPOILER_TYPE } from './../../ricos-content/index.js';
import type { RichContent } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import { buildThemeCssVars } from './../../ricos-styles/index.js';
import type {
  NodeViewDecorator,
  NodeViewRenderers,
  ViewerContextualData,
} from './../../ricos-types/index.js';
import { hasPlugin } from './../../_shared/has-plugin.js';
import {
  AccessibilityListener,
  GlobalContext,
  getLangDir,
} from './../../wix-rich-content-common/index.js';

import viewerStyles from '../statics/rich-content-viewer-scss.js';
import rtlStyles from '../statics/rtl-scss.js';
import type { ContentViewerProps } from '../types.js';
import { AddAnchors } from './components/add-anchors.js';
import { ContentTraverser } from './content-traverser.js';
import { ANIMATION_SCOPE_ATTR, NodeAnimations } from './node-animations.js';

const styles = { ...viewerStyles, ...rtlStyles };

// React.useId ships in 18+, but the classic editor still mounts the viewer under a
// React 16 host runtime, where calling it throws and takes the whole viewer down
// with it. Those hosts render client-side only, so a module counter is a safe
// stand-in there; SSR-capable hosts (18+) keep the hydration-stable useId.
let animationScopeCounter = 0;
const useIdCompat: () => string =
  React.useId ??
  function useIdFallback() {
    const ref = useRef<string>();
    if (ref.current === undefined) {
      ref.current = `fallback${animationScopeCounter++}`;
    }
    return ref.current;
  };

export const ContentViewer: React.FC<ContentViewerProps> = props => {
  const {
    config = {},
    onHover,
    isMobile = false,
    addAnchors,
    onMouseOver = () => {},
    content,
    setRef,
    typeMappers,
    nodeViewRenderers,
    nodeViewDecorators,
    experiments = {},
    t,
  } = props;

  const [minHeight, setMinHeight] = useState<number | undefined>(undefined);
  const viewerRef = useRef<HTMLDivElement | null>(null);
  const contentRef = useRef<HTMLDivElement | null>(null);

  // SAFARI BUG FIX: Safari jumps to wrong scroll position during rerenders
  // ResizeObserver watches inner content and applies min-height to outer viewer container to prevent jumping
  useLayoutEffect(() => {
    const isSafari = /Safari/.test(navigator.userAgent) && !/Chrome/.test(navigator.userAgent);
    if (!isSafari || !contentRef.current) {
      return;
    }

    const resizeObserver = new ResizeObserver(entries => {
      const newHeight = entries[0].contentRect.height;
      if (newHeight > 0) {
        setMinHeight(newHeight);
      }
    });

    resizeObserver.observe(contentRef.current);

    return () => {
      resizeObserver.disconnect();
    };
  }, [content]);

  const handleRef = useCallback(
    (node: HTMLDivElement | null) => {
      viewerRef.current = node;
      if (setRef) {
        (setRef as React.MutableRefObject<HTMLDivElement | null>).current = node;
      }
    },
    [setRef]
  );

  const SpoilerViewerWrapper = config[SPOILER_TYPE]?.SpoilerViewerWrapper;
  const contextualData = getContextualData(props);
  const animationsEnabled = hasPlugin(ANIMATION_TYPE, contextualData.plugins);
  // Bounds this instance's animation hide CSS to its own content (see node-animations.tsx).
  // useId is stable across SSR and hydration; the delimiters it wraps ids in (`:r0:` on
  // React 18, `«r0»` on 19) are not valid in an unquoted CSS attribute value, and quoting
  // is not an option there, so it is reduced to a bare identifier. React's ids differ only
  // in the characters between the delimiters, so stripping them preserves uniqueness.
  const animationScopeId = `ricos-anim-${useIdCompat().replace(/[^a-zA-Z0-9]/g, '')}`;

  const viewerClassName = classNames(styles.viewer, {
    [rtlStyles.rtl]: contextualData.textDirection === 'rtl',
  });

  const style = buildThemeCssVars(contextualData.theme, content?.documentStyle ?? {});

  const dataId = { 'data-id': 'content-viewer' };

  return (
    <GlobalContext.Provider key={'RicosViewer'} value={{ experiments, isMobile, t }}>
      <div
        className={classNames(styles.wrapper)}
        dir={contextualData.languageDir}
        style={{
          ...style,
          minHeight: minHeight ? `${minHeight}px` : undefined,
        }}
        onMouseEnter={e => onHover && onHover(e)}
        onMouseOver={onMouseOver}
        ref={handleRef}
        {...dataId}
      >
        {props.devTools}
        <NodeAnimations
          content={content}
          contentRef={contentRef}
          enabled={animationsEnabled}
          scopeId={animationScopeId}
        />
        <div
          className={viewerClassName}
          ref={contentRef}
          {...(animationsEnabled ? { [ANIMATION_SCOPE_ATTR]: animationScopeId } : {})}
        >
          <AddAnchors addAnchors={addAnchors}>
            <ContentTraverser
              content={content as RichContent}
              typeMappers={typeMappers}
              context={contextualData}
              nodeViewRenderers={nodeViewRenderers as NodeViewRenderers}
              nodeViewDecorators={nodeViewDecorators as NodeViewDecorator<JSX.Element>[]}
              SpoilerViewerWrapper={SpoilerViewerWrapper}
            />
          </AddAnchors>
        </div>
        <AccessibilityListener isMobile={isMobile} />
      </div>
    </GlobalContext.Provider>
  );
};

const getContextualData = ({
  t,
  theme,
  plugins,
  isMobile = false,
  anchorTarget,
  relValue,
  customAnchorScroll,
  config,
  locale,
  disabled,
  seoMode,
  iframeSandboxDomain,
  textAlignment,
  experiments,
  textDirection,
  direction,
  helpers,
  onNodeClick,
  jsdomMode,
  baseUrl,
  userDomainMedia,
  isPrint,
}: ContentViewerProps): ViewerContextualData => {
  return {
    t,
    theme: theme || {},
    isMobile,
    anchorTarget,
    relValue,
    customAnchorScroll,
    config,
    helpers: helpers || {},
    locale: locale || 'en',
    disabled,
    seoMode: seoMode ?? (isPrint ? {} : undefined),
    iframeSandboxDomain,
    disableRightClick: config?.uiSettings?.disableRightClick,
    textAlignment,
    experiments,
    textDirection,
    languageDir: direction || getLangDir(locale),
    onNodeClick,
    jsdomMode,
    baseUrl,
    userDomainMedia,
    isPrint,
    plugins,
  };
};
