import type { RefObject } from 'react';
import React, { Component, Suspense, createRef, useEffect, useMemo } from 'react';

import { resolveFileUrl } from './../ricos-media/index.js';
import { VERTICAL_EMBED_TYPE, Version } from './../ricos-content/index.js';
import type { RichContent } from './../ricos-schema/legacy/wix/rich_content/v1/index.js';
import { resolveTheme } from './../ricos-styles/resolve-theme.js';
import { ThemeProvider } from './../ricos-styles/theme-provider.js';
import type { BICallbacks, SEOSettings } from './../ricos-types/index.js';
import { useBiHelpers } from './../_shared/bi-strategy/use-bi-helpers.js';
import { deepMerge } from './../_shared/deep-merge.js';
import { extractPluginsConfig } from './../_shared/extract-plugins-config.js';
import { hasPlugin } from './../_shared/has-plugin.js';
import { parseInstance } from './../_shared/request-service-provider/parse-instance.js';
import { RequestServiceProvider } from './../_shared/request-service-provider/request-service-provider.js';
import { WixInstanceContextProvider } from './../_shared/request-service-provider/wix-instance-context.js';
import { getImageUrl } from './../_shared/url-resolvers.js';
import { useIframeSandboxDomain } from './../_shared/use-iframe-sandbox-domain.js';
import { addDevToolsClickListener } from './../wix-rich-content-common/index.js';
import {
  RicosDevToolsLazy,
  shouldShowDebuggingInfo,
} from './../wix-rich-content-common/lib/dev-tools.js';
import { getContentSummary } from './../wix-rich-content-common/lib/ricos-content-analytics.js';

import { changeBaseUrl } from './change-base-url.js';
import { ContentViewer } from './ContentViewer/index.js';
import { isViewerPlugin } from './is-viewer-plugin.js';
import type { RicosViewerProps } from './types.js';
import { mergeViewerProps } from './utils.js';

type InternalViewerProps = RicosViewerProps & {
  pluginConfig?: Record<string, any>;
  helpers?: Record<string, any>;
};

interface State {
  error?: string;
  TextSelectionToolbar?: $TSFixMe;
  debugInvokedWithMouse?: boolean;
  content?: RichContent;
}

class RicosViewerNext extends Component<InternalViewerProps, State> {
  viewerRef!: RefObject<any>;

  getBiCallback: <T extends keyof BICallbacks>(key: T) => BICallbacks[T] | undefined;

  static displayName = 'RicosViewerNext';

  static getDerivedStateFromError(error: string) {
    return { error };
  }

  componentDidCatch(error: $TSFixMe, errorInfo: $TSFixMe) {
    console.error({ error, errorInfo });
  }

  constructor(props: RicosViewerProps) {
    super(props);
    this.getBiCallback = key => {
      const { children, helpers } = this.props;
      return children?.props.helpers?.[key] || helpers?.[key];
    };
    this.viewerRef = createRef();
    this.state = {};
  }

  static defaultProps = {
    onError: (err: $TSFixMe) => {
      throw err;
    },
  };

  componentDidMount() {
    addDevToolsClickListener(this.viewerRef.current, () =>
      this.setState({ debugInvokedWithMouse: true })
    );
  }

  loadTextSelection = () => {
    const { textSelectionToolbar, isMobile } = this.props;
    const needTextSelectionToolbar = textSelectionToolbar && !isMobile;
    if (needTextSelectionToolbar && !this.state.TextSelectionToolbar) {
      const TextSelectionToolbar = React.lazy(() => import('./text-selection-toolbar.js'));
      this.setState({ TextSelectionToolbar });
    }
  };

  onMouseOver = () => {
    this.loadTextSelection();
  };

  render() {
    const { seoSettings, mediaSettings, content, debugMode, isPrint } = this.props;
    const { TextSelectionToolbar } = this.state;
    const mergedProps = mergeViewerProps({
      ...this.props,
      viewerProps: {
        seoMode: seoSettings as SEOSettings | undefined,
        onMouseOver: this.onMouseOver,
        locale: this.props.locale,
        isPrint,
      },
    });

    try {
      if (this.state.error) {
        this.props.onError?.(this.state.error);
        return null;
      }
      return [
        <ContentViewer
          {...mergedProps}
          content={this.state.content ?? mergedProps.content}
          config={mergedProps.config}
          onHover={() => {}}
          key="viewer"
          setRef={this.viewerRef}
          fullscreenProps={mediaSettings?.fullscreenProps}
          devTools={
            this.state.debugInvokedWithMouse ||
            shouldShowDebuggingInfo(debugMode?.includes('all')) ? (
              <React.Suspense>
                <RicosDevToolsLazy
                  schema={{
                    getContent: () => (this.state.content ?? mergedProps.content) as RichContent,
                    setContent: content => this.setState({ content }),
                  }}
                  version={Version.currentVersion}
                  mode="viewer"
                  contentState={content}
                  ricosProps={this.props}
                  autoOpen={this.state.debugInvokedWithMouse ?? false}
                />
              </React.Suspense>
            ) : null
          }
        />,
        TextSelectionToolbar ? (
          <Suspense key="TextSelectionToolbar" fallback={<div />}>
            <TextSelectionToolbar
              onButtonClick={this.getBiCallback('onViewerAction')}
              container={this.viewerRef.current}
            />
          </Suspense>
        ) : null,
      ];
    } catch (e) {
      // @ts-ignore $TSFixMe
      this.props.onError?.(e);
      return null;
    }
  }
}

/**
 * Wrapper component that lazy loads BI helpers and passes them to the class component.
 * Waits for BI helpers to load before rendering the viewer to ensure onViewerLoaded
 * has access to the loaded helpers.
 */
export const RicosViewerWithHelpers = (props: RicosViewerProps) => {
  const {
    biSettings,
    instance,
    wixClient,
    iframeSandboxDomain: explicitDomain,
    theme,
    baseUrl,
    ...restProps
  } = props;

  // Lazy load BI helpers only when biSettings AND instance are provided
  const { helpers: biHelpers, biLoadPromise } = useBiHelpers({ instance, biSettings });

  const { metaSiteId } = useMemo(() => parseInstance(props.instance), [props.instance]);

  // Fire onViewerLoaded once BI helpers finish loading
  useEffect(() => {
    biLoadPromise.then(callbacks => {
      const content = props.content;
      const { pluginsCount } = (content && getContentSummary(content)) || {};
      if (pluginsCount) {
        callbacks.onViewerLoaded?.({
          isPreview: false,
          version: Version.currentVersion,
          pluginsCount,
          url: document.URL,
          contentId: content?.metadata?.id,
        });
      }
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Compute iframeSandboxDomain from instance if not explicitly provided
  const iframeSandboxDomain = useIframeSandboxDomain(explicitDomain, instance);

  // Resolve Wix theme strategy (liveSite/wixStyle/nativeStyle)
  const resolvedTheme = useMemo(
    () => resolveTheme({ theme, isMobile: restProps.isMobile }),
    [theme, restProps.isMobile]
  );

  const viewerPlugins = useMemo(() => props.plugins?.filter(isViewerPlugin), [props.plugins]);

  const extractedPluginConfig = useMemo(() => extractPluginsConfig(viewerPlugins), [viewerPlugins]);

  const verticalEmbedConfig = useMemo(() => {
    if (baseUrl && hasPlugin(VERTICAL_EMBED_TYPE, viewerPlugins)) {
      return {
        [VERTICAL_EMBED_TYPE]: {
          changeBaseUrl: (url: string) => changeBaseUrl(url, baseUrl),
        },
      };
    }
    return {};
  }, [baseUrl, viewerPlugins]);

  const pluginConfig = useMemo(
    () => deepMerge({}, extractedPluginConfig.config, verticalEmbedConfig),
    [extractedPluginConfig, verticalEmbedConfig]
  );

  const helpers = useMemo(
    () => ({
      ...biHelpers,
      getImageUrl,
      resolveFileUrl:
        // Some urls might be resolved even without msid or instance, so we call it regardless
        resolveFileUrl(props.msid ?? metaSiteId ?? '', props.instance ?? ''),
    }),
    [biHelpers, props.msid, props.instance, metaSiteId]
  );

  return (
    <RequestServiceProvider wixClient={wixClient} instance={instance}>
      <WixInstanceContextProvider instance={instance}>
        <ThemeProvider theme={resolvedTheme}>
          <RicosViewerNext
            {...restProps}
            msid={props.msid ?? metaSiteId}
            pluginConfig={pluginConfig}
            helpers={helpers}
            iframeSandboxDomain={iframeSandboxDomain}
            theme={resolvedTheme}
            baseUrl={baseUrl}
          />
        </ThemeProvider>
      </WixInstanceContextProvider>
    </RequestServiceProvider>
  );
};
RicosViewerWithHelpers.displayName = 'RicosViewer';
