import type { Node } from './../../../ricos-schema/next-schema/index.js';
import { getNodeAnimation } from './../../../_shared/node-animation/get-node-animation.js';

/**
 * Early-exit recursive scan: does any node in the tree carry a mouse (`POINTER`)
 * animation? Pointer docs take a harder overflow clip than entrance/loop-only docs —
 * see the rationale in node-animations.tsx.
 */
export const hasPointerAnimatedNodes = (nodes: Node[]): boolean =>
  nodes.some(
    node => getNodeAnimation(node)?.type === 'POINTER' || hasPointerAnimatedNodes(node.nodes ?? [])
  );
