/* oxlint-disable-next-line import/extensions */
import { getMonoid as getMonoidArray, map } from 'fp-ts-esm/Array';
/* oxlint-disable-next-line import/extensions */
import { pipe } from 'fp-ts-esm/function';
/* oxlint-disable-next-line import/extensions */
import { fold, struct } from 'fp-ts-esm/Monoid';
/* oxlint-disable-next-line import/extensions */
import { getMonoid as getMonoidRecord } from 'fp-ts-esm/Record';
/* oxlint-disable-next-line import/extensions */
import { last } from 'fp-ts-esm/Semigroup';

import type { Node_Type } from './../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type {
  NodeViewDecorator,
  NodeViewRenderer,
  PluginTypeMapper,
  ViewerPlugin,
} from './../ricos-types/index.js';
import { deepMerge } from './../_shared/deep-merge.js';

import type { ContentViewerProps, RCVPluginProps } from './types.js';

const recordMergeM = <T>() => getMonoidRecord<string, T>(last<T>());
const nodeViewRenderersMergeM = () => getMonoidRecord<Node_Type, NodeViewRenderer>(last());
const rcvPropM = struct<RCVPluginProps>({
  config: recordMergeM<any>(),
  typeMappers: getMonoidArray<PluginTypeMapper>(),
  nodeViewDecorators: getMonoidArray<NodeViewDecorator<JSX.Element>>(),
  // @ts-ignore $TSFixMe
  nodeViewRenderers: nodeViewRenderersMergeM(),
});
const extractChildRCVPluginProps = ({
  config = {},
  typeMappers = [],
  nodeViewRenderers,
  nodeViewDecorators,
}: any): RCVPluginProps => ({
  config,
  typeMappers,
  nodeViewRenderers,
  nodeViewDecorators,
});

const toRCVPluginProps =
  () =>
  (plugin: ViewerPlugin): RCVPluginProps => {
    const pluginProps: RCVPluginProps = {
      config: { [plugin.type]: plugin.config },
      typeMappers: [],
      nodeViewRenderers: {},
      nodeViewDecorators: [],
    };

    if (plugin.nodeViewRenderers) {
      pluginProps.nodeViewRenderers = plugin.nodeViewRenderers;
    } else if (plugin.typeMapper) {
      pluginProps.typeMappers = [plugin.typeMapper];
    }

    pluginProps.nodeViewDecorators = plugin.nodeViewDecorators ? plugin.nodeViewDecorators : [];

    return pluginProps;
  };

const mergeWithChildProps = (childPluginProps: $TSFixMe) => (pluginProps: $TSFixMe) =>
  deepMerge({}, pluginProps, childPluginProps);

export function pluginsStrategy({
  plugins = [],
  viewerProps,
}: {
  plugins: ViewerPlugin[];
  viewerProps: Partial<ContentViewerProps>;
}): RCVPluginProps {
  return pipe(
    plugins as ViewerPlugin[],
    map(toRCVPluginProps()),
    fold(rcvPropM),
    mergeWithChildProps(extractChildRCVPluginProps(viewerProps))
  );
}
